// -- §13.2 config INI -------------------------------------------------------------

static StoreConfig configFromEncodeCase(const DacarFixtures::IniEncodeCase& c) {
	StoreConfig config;
	config.primary_salt = bytesFromHex(c.primary_hex);
	config.legacy_salts = bytesVecFromHex(c.legacy_hex);
	config.anchors = bytesVecFromHex(c.anchors_hex);
	if (c.authoritative_hex && c.authoritative_hex[0]) {
		config.authoritative = bytesFromHex(c.authoritative_hex);
	}
	config.horizon_days = c.horizon_days;
	config.rfed_topic = c.rfed_topic;
	if (c.rfed_node_hex && c.rfed_node_hex[0]) {
		config.rfed_node = bytesFromHex(c.rfed_node_hex);
	}
	if (c.lxmf_proprietor_hex && c.lxmf_proprietor_hex[0]) {
		config.lxmf_proprietor = bytesFromHex(c.lxmf_proprietor_hex);
	}
	return config;
}

static RNS::Bytes bytesFromHexStr(const std::string& hex) {
	return bytesFromHex(hex.c_str());
}

static RNS::Bytes fillBytes(size_t size, uint8_t value) {
	RNS::Bytes out(size);
	memset(out.writable(size), value, size);
	return out;
}

void testIniEncodeMatchesPython() {
	for (size_t i = 0; i < DacarFixtures::INI_ENCODE_CASE_COUNT; i++) {
		const auto& c = DacarFixtures::INI_ENCODE_CASES[i];
		const std::string ini = encode_config_ini(configFromEncodeCase(c));
		const RNS::Bytes expected = bytesFromHexStr(c.expected_hex);
		const RNS::Bytes actual(ini.data(), ini.size());
		TEST_ASSERT_EQUAL_MEMORY(expected.data(), actual.data(), expected.size());
	}
}

void testIniDecodeMatchesPython() {
	for (size_t i = 0; i < DacarFixtures::INI_DECODE_CASE_COUNT; i++) {
		const auto& c = DacarFixtures::INI_DECODE_CASES[i];
		const StoreConfig config = decode_config_ini(bytesFromHexStr(c.ini_hex));
		TEST_ASSERT_TRUE(config.primary_salt == bytesFromHexStr(c.primary_hex));
		TEST_ASSERT_TRUE(config.authoritative == bytesFromHexStr(c.authoritative_hex));
		TEST_ASSERT_TRUE(config.rfed_node == bytesFromHexStr(c.rfed_node_hex));
		TEST_ASSERT_TRUE(config.lxmf_proprietor == bytesFromHexStr(c.lxmf_proprietor_hex));
		TEST_ASSERT_EQUAL_INT(c.horizon_days, config.horizon_days);
		TEST_ASSERT_EQUAL_STRING(c.rfed_topic, config.rfed_topic.c_str());
		auto legacy = bytesVecFromHex(c.legacy_hex);
		auto anchors = bytesVecFromHex(c.anchors_hex);
		TEST_ASSERT_EQUAL_size_t(legacy.size(), config.legacy_salts.size());
		for (size_t k = 0; k < legacy.size(); k++) {
			TEST_ASSERT_TRUE(legacy[k] == config.legacy_salts[k]);
		}
		TEST_ASSERT_EQUAL_size_t(anchors.size(), config.anchors.size());
		for (size_t k = 0; k < anchors.size(); k++) {
			TEST_ASSERT_TRUE(anchors[k] == config.anchors[k]);
		}
	}
}

void testIniRoundTrip() {
	for (size_t i = 0; i < DacarFixtures::INI_ENCODE_CASE_COUNT; i++) {
		const auto& c = DacarFixtures::INI_ENCODE_CASES[i];
		const StoreConfig original = configFromEncodeCase(c);
		const std::string ini = encode_config_ini(original);
		const StoreConfig decoded = decode_config_ini(RNS::Bytes(ini.data(), ini.size()));
		const std::string again = encode_config_ini(decoded);
		TEST_ASSERT_EQUAL_STRING(ini.c_str(), again.c_str());
	}
}

void testIniDecodeRejectsMalformed() {
	// Bad salt length.
	TEST_ASSERT_THROW(decode_config_ini(bytesFromHexStr(
		std::string("5b73616c745d0a7072696d617279203d2030300a")  // "[salt]\nprimary = 00\n"
	)), std::invalid_argument);
	// Bad horizon integer.
	TEST_ASSERT_THROW(decode_config_ini(bytesFromHexStr(
		std::string("5b706f6c6963795d0a64656c6574696f6e5f686f72697a6f6e5f64617973203d206162630a")  // "[policy]\ndeletion_horizon_days = abc\n"
	)), std::invalid_argument);
}

// -- §13.3 clock ---------------------------------------------------------------------

void testClockPayloadMatchesPython() {
	for (size_t i = 0; i < DacarFixtures::CLOCK_FILE_CASE_COUNT; i++) {
		const auto& c = DacarFixtures::CLOCK_FILE_CASES[i];
		const RNS::Bytes encoded = encode_clock_payload(Clock(c.last_ms, c.logical));
		const RNS::Bytes expected = bytesFromHexStr(c.expected_hex);
		TEST_ASSERT_EQUAL_MEMORY(expected.data(), encoded.data(), expected.size());
		const Clock decoded = decode_clock_payload(expected);
		TEST_ASSERT_EQUAL_UINT64(c.last_ms, decoded.last_ms());
		TEST_ASSERT_EQUAL_UINT64(c.logical, decoded.logical());
	}
}

void testClockDecodeTolerant() {
	// nil, an array, and empty input all decode to a fresh Clock.
	const Clock nilClock = decode_clock_payload(bytesFromHexStr("c0"));
	TEST_ASSERT_EQUAL_UINT64(0, nilClock.last_ms());
	TEST_ASSERT_EQUAL_UINT64(0, nilClock.logical());
	const Clock arrayClock = decode_clock_payload(bytesFromHexStr("90"));
	TEST_ASSERT_EQUAL_UINT64(0, arrayClock.last_ms());
	const Clock emptyClock = decode_clock_payload(RNS::Bytes());
	TEST_ASSERT_EQUAL_UINT64(0, emptyClock.last_ms());
}

// -- §13.6 ledger ----------------------------------------------------------------------

static void fillLedgerFromCase(const DacarFixtures::LedgerFileCase& c, Ledger& ledger) {
	for (size_t r = 0; r < c.row_count; r++) {
		const auto& row = c.rows[r];
		const RNS::Bytes tupleHash = bytesFromHexStr(row.tuple_hash_hex);
		const std::string object = row.object ? row.object : "";
		const std::string relation = row.relation ? row.relation : "";
		if (object.empty() && relation.empty() && row.wildcard < 0) {
			ledger.ensure(tupleHash);
			if (!relation.empty()) {
				ledger.annotate(tupleHash, {}, relation);
			}
		}
		else {
			ledger.record(
				tupleHash,
				object.c_str(),
				relation.c_str(),
				row.wildcard > 0,
				row.first_seen
			);
		}
	}
}

void testLedgerPayloadMatchesPython() {
	for (size_t i = 0; i < DacarFixtures::LEDGER_FILE_CASE_COUNT; i++) {
		const auto& c = *DacarFixtures::LEDGER_FILE_CASES[i];
		Ledger ledger;
		// The "recorded_and_annotated" case exercises ensure()+annotate()
		// for its second row (nil object/wildcard but a named relation),
		// mirroring how the fixture generator built the reference bytes.
		if (std::string(c.comment) == "recorded_and_annotated") {
			const auto& full = c.rows[0];
			ledger.record(
				bytesFromHexStr(full.tuple_hash_hex),
				full.object,
				full.relation,
				full.wildcard > 0,
				full.first_seen
			);
			const auto& partial = c.rows[1];
			ledger.ensure(bytesFromHexStr(partial.tuple_hash_hex));
			ledger.annotate(bytesFromHexStr(partial.tuple_hash_hex), {}, partial.relation);
		}
		else {
			fillLedgerFromCase(c, ledger);
		}
		const RNS::Bytes encoded = encode_ledger_payload(ledger);
		const RNS::Bytes expected = bytesFromHexStr(c.expected_hex);
		TEST_ASSERT_EQUAL_MEMORY(expected.data(), encoded.data(), expected.size());
		// Decoding reference bytes yields the same rows in the same order.
		const Ledger decoded = decode_ledger_payload(expected);
		TEST_ASSERT_EQUAL_size_t(ledger.rows().size(), decoded.rows().size());
		for (size_t r = 0; r < ledger.rows().size(); r++) {
			TEST_ASSERT_EQUAL_STRING(ledger.rows()[r].first.c_str(), decoded.rows()[r].first.c_str());
			const auto& a = ledger.rows()[r].second;
			const auto& b = decoded.rows()[r].second;
			TEST_ASSERT_TRUE(a.object.has_value() == b.object.has_value());
			if (a.object.has_value()) {
				TEST_ASSERT_EQUAL_STRING((*a.object).c_str(), (*b.object).c_str());
			}
			TEST_ASSERT_TRUE(a.relation.has_value() == b.relation.has_value());
			if (a.relation.has_value()) {
				TEST_ASSERT_EQUAL_STRING((*a.relation).c_str(), (*b.relation).c_str());
			}
			TEST_ASSERT_TRUE(a.wildcard.has_value() == b.wildcard.has_value());
			TEST_ASSERT_EQUAL_UINT64(a.first_seen, b.first_seen);
		}
	}
}

void testLedgerKeepsEarliestFirstSeen() {
	Ledger ledger;
	const RNS::Bytes th = bytesFromHexStr(
		"6361393738313132636131626264636166616332333162333961323364633464613738366566663831343763346537326239383037373835616665653438626282"
	);
	ledger.record(th, "engine", "start", false, 200);
	ledger.record(th, "engine", "start", false, 100);
	const LedgerRow* row = ledger.lookup(th);
	TEST_ASSERT_NOT_NULL(row);
	TEST_ASSERT_EQUAL_UINT64(100, row->first_seen);
}

// -- §13.7 identities ---------------------------------------------------------------------

void testIdentitiesPayloadMatchesPython() {
	for (size_t i = 0; i < DacarFixtures::IDENTITIES_FILE_CASE_COUNT; i++) {
		const auto& c = DacarFixtures::IDENTITIES_FILE_CASES[i];
		Keyring keyring;
		for (const auto& blob : bytesVecFromHex(c.hash_pubs_hex)) {
			RNS::Bytes hash(blob.data(), 16);
			RNS::Bytes pub(blob.data() + 16, 32);
			keyring.register_single(hash, pub);
		}
		const RNS::Bytes encoded = encode_keyring_payload(keyring);
		const RNS::Bytes expected = bytesFromHexStr(c.expected_hex);
		TEST_ASSERT_EQUAL_MEMORY(expected.data(), encoded.data(), expected.size());
		// Decoding reference bytes resolves every issuer.
		const Keyring decoded = decode_keyring_payload(expected);
		TEST_ASSERT_EQUAL_size_t(keyring.size(), decoded.size());
		for (const auto& [hash, keyset] : keyring.entries()) {
			const IssuerKeyset* resolved = decoded.resolve(hash);
			TEST_ASSERT_NOT_NULL(resolved);
			TEST_ASSERT_TRUE(resolved->member_public_keys()[0] == keyset.member_public_keys()[0]);
		}
	}
}

void testIdentitiesDecodeDropsWrongLength() {
	// A map entry whose value is 16 bytes (not 32) is dropped on load.
	const RNS::Bytes poisoned = bytesFromHexStr(
		"d920303130313031303130313031303130313031303130313031303130313031c410"
		"3031323032303230323032303230323032303230"
	);
	const Keyring keyring = decode_keyring_payload(poisoned);
	TEST_ASSERT_EQUAL_size_t(0, keyring.size());
}

void testKeyringInsertionOrder() {
	// Registration order is preserved; overwriting keeps position; forget
	// compacts without disturbing the order of the rest (Python dict parity).
	Keyring keyring;
	const RNS::Bytes a = bytesFromHexStr("01010101010101010101010101010101");
	const RNS::Bytes b = bytesFromHexStr("02020202020202020202020202020202");
	const RNS::Bytes c = bytesFromHexStr("03030303030303030303030303030303");
	const RNS::Bytes pubA = fillBytes(32, 0xA1);
	const RNS::Bytes pubB = fillBytes(32, 0xB2);
	const RNS::Bytes pubC = fillBytes(32, 0xC3);
	keyring.register_single(b, pubB);
	keyring.register_single(a, pubA);
	keyring.register_single(a, pubA); // overwrite in place
	keyring.register_single(c, pubC);
	auto entries = keyring.entries();
	TEST_ASSERT_EQUAL_size_t(3, entries.size());
	TEST_ASSERT_TRUE(entries[0].first == b);
	TEST_ASSERT_TRUE(entries[1].first == a);
	TEST_ASSERT_TRUE(entries[2].first == c);
	TEST_ASSERT_TRUE(keyring.forget(b));
	entries = keyring.entries();
	TEST_ASSERT_EQUAL_size_t(2, entries.size());
	TEST_ASSERT_TRUE(entries[0].first == a);
	TEST_ASSERT_TRUE(entries[1].first == c);
	TEST_ASSERT_NULL(keyring.resolve(b));
	TEST_ASSERT_NOT_NULL(keyring.resolve(a));
	// Re-registering a forgotten hash appends at the end.
	keyring.register_single(b, pubB);
	entries = keyring.entries();
	TEST_ASSERT_EQUAL_size_t(3, entries.size());
	TEST_ASSERT_TRUE(entries[2].first == b);
}

